import type { ProjectId } from './Project';

export const entryPointCandidateReasons = [
  'exactFilenameMatch',
  'filenameMatch',
  'pathMatch',
  'textMatch',
  'headingMatch',
  'symbolLikeMatch',
  'semanticMatch',
  'manualPin',
] as const;

