// apps/mcp/tools/__tests__/candidateTransformer.test.ts
import { describe, expect, it } from 'vitest';
import { transformCandidates } from '../candidateTransformer';
import type { EnrichedEntryPointCandidate } from '../../../../src/features/repository-context/domain/CandidateEvidence';

describe('candidateTransformer', () => {
  const createEnriched = (relativePath: string): EnrichedEntryPointCandidate => ({
    candidate: {
      projectId: 'proj-1',
      relativePath,
      score: 80,
      reasons: ['exactFilenameMatch'],
      matchedTerms: ['test'],
    },
    evidence: [],
    supportScore: 50,
  });

  it('classifies code files correctly', () => {
    const candidates = [
      createEnriched('src/index.ts'),
      createEnriched('src/app.tsx'),
      createEnriched('src/utils.js'),
      createEnriched('src/Component.jsx'),
    ];

    const result = transformCandidates(candidates);

    expect(result).toHaveLength(4);
    result.forEach((dto) => {
      expect(dto.kind).toBe('code');
    });
  });

  it('classifies test files correctly', () => {
    const candidates = [
      createEnriched('src/__tests__/index.test.ts'),
      createEnriched('src/utils.spec.ts'),
      createEnriched('tests/e2e/flow.test.ts'),
    ];

    const result = transformCandidates(candidates);

    expect(result).toHaveLength(3);
    result.forEach((dto) => {
      expect(dto.kind).toBe('test');
    });
  });

  it('classifies document files correctly', () => {
    const candidates = [
      createEnriched('README.md'),
      createEnriched('docs/guide.mdx'),
      createEnriched('docs/architecture/design.md'),
    ];

    const result = transformCandidates(candidates);

    expect(result).toHaveLength(3);
    result.forEach((dto) => {
      expect(dto.kind).toBe('document');
    });
  });

  it('classifies config files correctly', () => {
    const candidates = [
      createEnriched('package.json'),
      createEnriched('tsconfig.json'),
      createEnriched('.env'),
      createEnriched('config.yaml'),
      createEnriched('setup.toml'),
    ];

    const result = transformCandidates(candidates);

    expect(result).toHaveLength(5);
    result.forEach((dto) => {
      expect(dto.kind).toBe('config');
    });
  });

  it('classifies unknown files as other', () => {
    const candidates = [
      createEnriched('README'),
      createEnriched('Makefile'),
      createEnriched('license.txt'),
    ];

    const result = transformCandidates(candidates);

    expect(result).toHaveLength(3);
    result.forEach((dto) => {
      expect(dto.kind).toBe('other');
    });
  });

  it('preserves all other candidate properties', () => {
    const evidence = [
      { kind: 'relatedTest' as const, relatedPath: 'tests/index.test.ts', detail: 'matching test' },
    ];
    const candidates: EnrichedEntryPointCandidate[] = [{
      candidate: {
        projectId: 'proj-1',
        relativePath: 'src/index.ts',
        score: 95,
        reasons: ['exactFilenameMatch', 'semanticMatch'],
        matchedTerms: ['index', 'main'],
      },
      evidence,
      supportScore: 75,
    }];

    const result = transformCandidates(candidates);

    expect(result).toHaveLength(1);
    const dto = result[0];
    expect(dto.relativePath).toBe('src/index.ts');
    expect(dto.kind).toBe('code');
    expect(dto.discoveryScore).toBe(95);
    expect(dto.supportScore).toBe(75);
    expect(dto.reasons).toEqual(['exactFilenameMatch', 'semanticMatch']);
    expect(dto.matchedTerms).toEqual(['index', 'main']);
    expect(dto.evidence).toHaveLength(1);
    expect(dto.evidence[0].kind).toBe('relatedTest');
  });
});

