// src/features/repository-context/domain/EntryPointCandidate.ts
import type { ProjectId } from './Project';

export const entryPointCandidateReasons = [
  'exactFilenameMatch',
  'filenameMatch',
  'pathMatch',
  'textMatch',
  'headingMatch',
  'symbolLikeMatch',
  'semanticMatch',
  'manualPin',
] as const;

export type EntryPointCandidateReason = (typeof entryPointCandidateReasons)[number];

export type EntryPointCandidateKind = 'code' | 'test' | 'document' | 'config' | 'other';

export type EntryPointCandidateEvidence = Readonly<{
  projectId: ProjectId;
  relativePath: string;
  reason: EntryPointCandidateReason;
  matchedTerm?: string;
}>;

export type EntryPointCandidate = Readonly<{
  projectId: ProjectId;
  relativePath: string;
  score: number;
  reasons: readonly EntryPointCandidateReason[];
  matchedTerms: readonly string[];
  kind?: EntryPointCandidateKind;
}>;

export const isEntryPointCandidateReason = (value: unknown): value is EntryPointCandidateReason =>
  typeof value === 'string' && entryPointCandidateReasons.includes(value as EntryPointCandidateReason);

const testPathPattern = /(__tests__|\.test\.|\.spec\.)/i;
const configExts = new Set(['json', 'yaml', 'yml', 'toml', 'xml', 'properties', 'ini', 'env']);
const docExts = new Set(['md', 'mdx']);

export const resolveCandidateKind = (relativePath: string): EntryPointCandidateKind => {
  const normalized = relativePath.replace(/\\/g, '/');
  if (testPathPattern.test(normalized)) return 'test';

  const ext = normalized.split('.').pop()?.toLowerCase() ?? '';
  if (docExts.has(ext)) return 'document';
  if (configExts.has(ext)) return 'config';
  if (/\.(ts|tsx|js|jsx|py|go|rs|java|c|cpp|cs|rb|php|h|hpp|sh|bash|zsh|sql|html|css|scss|swift|kt)$/.test(normalized.toLowerCase())) {
    return 'code';
  }
  return 'other';
};
